def step(label,cmd,limit):
    (report/(label+'.command.json')).write_text(json.dumps(cmd,indent=2)+'\n')
    with (report/(label+'.stdout.log')).open('wb') as out,(report/(label+'.stderr.log')).open('wb') as err,(report/(label+'.disk.jsonl')).open('w') as samples:
        process=subprocess.Popen(cmd,stdout=out,stderr=err,start_new_session=True);started=time.monotonic();reason=None
        while process.poll() is None:
            free=shutil.disk_usage(REVIEW).free;samples.write(json.dumps({'time':time.time(),'free_bytes':free})+'\n');samples.flush()
            if free<500*1024**2 or time.monotonic()-started>limit:
                reason='disk_below_500MiB' if free<500*1024**2 else 'timeout'
                os.killpg(process.pid,signal.SIGTERM)
                try:process.wait(timeout=15)
                except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=10)
                break
            time.sleep(1)
        code=process.wait()
    result={'step':label,'returncode':code,'reason':reason,'seconds':time.monotonic()-started};results.append(result)
    (report/(label+'.result.json')).write_text(json.dumps(result,indent=2)+'\n')
    print('BUILD_STEP',json.dumps(result),flush=True)
    print((report/(label+'.stdout.log')).read_text(errors='replace'),flush=True)
    print((report/(label+'.stderr.log')).read_text(errors='replace'),flush=True)
    return code==0 and reason is None

